function hostApply(m,id){
 if(m.t==='resync_request'){let snap=phase108Outbound({t:'state',st,resyncReason:m.reason||'client-request',requestId:m.requestId},{advance:true,lobbyAdvance:false});sendToSeat(id,snap);return{ok:true,resync:true}}
 if(m.t==='profile_update'){let p=players.find(x=>x.id===id);if(!p)return{ok:false,reason:'player-missing'};let name=String(m.name||p.name||('Player '+id)).trim().slice(0,120),commander=m.commander==null?p.commander:String(m.commander).slice(0,220),avatar=MTGAvatars.isValid(m.avatarId)?m.avatarId:(p.avatarId||MTGAvatars.DEFAULT_ID),deckName=m.deckName==null?p.deckName:String(m.deckName).slice(0,220);p.name=name||p.name;p.commander=commander;p.avatarId=avatar;p.deckName=deckName;p.deckSize=Math.max(1,Number(m.deckSize||p.deckSize||100));p.commanderCount=Math.max(1,Number(m.commanderCount||p.commanderCount||1));p.deckColorIdentity=typeof MTGBattleChronicle!=='undefined'?MTGBattleChronicle.normalizeIdentity(m.deckColorIdentity):[];slots();if(battleStarted)try{sync()}catch{};send({t:'players',players});return{ok:true}}
 if(m.t==='ready'){let p=players.find(x=>x.id===id);if(!p)return{ok:false,reason:'player-missing'};p.r=1;p.connected=true;slots();send({t:'players',players});return{ok:true}}
 if(m.t==='cmd'){if(!rememberRequest(m.requestId))return{ok:true,duplicate:true};if(!validCommand(m.c,m.p)){toast('Rejected invalid command from Player '+id);return{ok:false,reason:'invalid-command'}}let target=(['damage','lifeLoss'].includes(m.c)&&Number.isInteger(Number(m.p?.targetId)))?Number(m.p.targetId):id;if(!players.some(p=>p.id===target)){toast('Rejected invalid target from Player '+id);return{ok:false,reason:'invalid-target'}}let ok=apply(m.c,m.p,target,{clientId:m.clientId||null,requestId:m.requestId,sourceActorId:id});return{ok:ok!==false,reason:ok===false?'command-rejected':null}}
 if(m.t==='respond'){if(!rememberRequest(m.requestId))return{ok:true,duplicate:true};let gate=priorityMessageGate(m,id,'respond');if(!gate.ok)return{ok:false,reason:gate.reason||'priority-rejected'};let ok=priorityRespond(id,{clientId:m.clientId||null,source:'client'});return{ok:ok!==false,reason:ok===false?'priority-rejected':null}}
 if(m.t==='pass'){if(!rememberRequest(m.requestId))return{ok:true,duplicate:true};let gate=priorityMessageGate(m,id,'pass');if(!gate.ok)return{ok:false,reason:gate.reason||'priority-rejected'};let ok=priorityPass(id,{clientId:m.clientId||null,source:'client'});return{ok:ok!==false,reason:ok===false?'priority-rejected':null}}
 return{ok:false,reason:'unsupported-client-message'}
}

